-- Dữ liệu (16/11/2026, đã được duyệt). Chạy lại không tạo trùng.
-- A) FC Online thi đấu ĐỒNG ĐỘI theo luật EA (FC Pro Champions Cup / Masters: mỗi đội 3–4 tuyển thủ, mỗi trận gồm
--    các ván 1v1 giữa từng tuyển thủ) -> Game FC Online: 3 chính thức + 1 dự bị. 13 đội FC Online được bổ sung tuyển
--    thủ demo; 4 giải FC Online đổi số chính thức = 3 (dự bị tối đa 1); đội hình các đơn bổ sung theo.
-- B) 6 giải ĐANG NHẬN ĐĂNG KÝ đã bị sinh nhánh sớm (10, 13, 14, 17, 20, 22) -> xóa nhánh tạm (chỉ trận chưa đấu:
--    PENDING/READY, không tỉ số, không người thắng). UC: BTC đóng đăng ký rồi mới sinh nhánh. Livestream gắn trận
--    bị xóa được giữ lại, chỉ bỏ liên kết trận.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_as_ci;
-- ===== B) Xóa nhánh tạm của giải còn nhận đăng ký =====
UPDATE Livestream l JOIN `Match` m ON m.MatchID = l.MatchID JOIN Tournament t ON t.TournamentID = m.TournamentID SET l.MatchID = NULL WHERE t.TournamentID IN (10, 13, 14, 17, 20, 22) AND t.Status = 'PUBLISHED' AND t.BracketLockedAt IS NULL AND UTC_TIMESTAMP() < t.RegCloseAt AND m.Status IN ('PENDING', 'READY') AND m.WinnerTeamID IS NULL AND m.ScoreA IS NULL AND m.ScoreB IS NULL;
DELETE m FROM `Match` m JOIN Tournament t ON t.TournamentID = m.TournamentID WHERE t.TournamentID IN (10, 13, 14, 17, 20, 22) AND t.Status = 'PUBLISHED' AND t.BracketLockedAt IS NULL AND UTC_TIMESTAMP() < t.RegCloseAt AND m.Status IN ('PENDING', 'READY') AND m.WinnerTeamID IS NULL AND m.ScoreA IS NULL AND m.ScoreB IS NULL;
UPDATE BracketNode b JOIN Tournament t ON t.TournamentID = b.TournamentID SET b.ParentNodeID = NULL WHERE t.TournamentID IN (10, 13, 14, 17, 20, 22) AND t.Status = 'PUBLISHED' AND t.BracketLockedAt IS NULL AND UTC_TIMESTAMP() < t.RegCloseAt AND NOT EXISTS (SELECT 1 FROM `Match` x WHERE x.TournamentID = t.TournamentID);
DELETE b FROM BracketNode b JOIN Tournament t ON t.TournamentID = b.TournamentID WHERE t.TournamentID IN (10, 13, 14, 17, 20, 22) AND t.Status = 'PUBLISHED' AND t.BracketLockedAt IS NULL AND UTC_TIMESTAMP() < t.RegCloseAt AND NOT EXISTS (SELECT 1 FROM `Match` x WHERE x.TournamentID = t.TournamentID);
-- ===== A) FC Online: 3 chính thức + 1 dự bị =====
UPDATE Game SET MinStarters = 3, MaxStarters = 3, MaxSubstitutes = 1 WHERE GameID = 7 AND ShortCode = 'FCO';
UPDATE Tournament SET StarterCount = 3, MaxSubstitutes = GREATEST(MaxSubstitutes, 1) WHERE GameID = 7 AND StarterCount < 3;
